node --input-type=module -e "
import { readFileSync } from 'node:fs';
import path from 'node:path';
import { GLB } from './js/glb.mjs';
import { Game } from './js/game.mjs';
function loadGlb(n){const g=new GLB(n);g.raw=new Uint8Array(readFileSync(path.resolve('data',n)));return g.parse();}
const glb1=loadGlb('FILE0001.GLB'), glb0=loadGlb('FILE0000.GLB');
function die(seed, fire){
  const game=new Game(glb1,glb0,{play(){},sfxCount:0,state:'running'});
  const r=s=>{let x=s>>>0;return()=>(x=(x*1664525+1013904223)>>>0)/4294967296;};
  const rnd=r(seed);
  let f=0;
  while(game.state==='playing' && f<50*60*5){
    game.input.fire=fire;
    game.input.up=true;
    game.input.left=game.input.right=false;
    const c=rnd();
    if (c<0.35) game.input.left=true; else if (c<0.7) game.input.right=true;
    if (game.playerx<40) { game.input.left=false; game.input.right=true; }
    if (game.playerx>260) { game.input.right=false; game.input.left=true; }
    game.frame(); f++;
  }
  console.log('fire='+fire,'seed',seed,'-> died at '+(f/50).toFixed(0)+'s sim (wave',game.wave+1,') or still alive at 5min');
}
for (const s of [1,2,3]) die(s,false);
for (const s of [1,2]) die(s,true);
" 2>&1

