import { readFileSync } from 'node:fs';
import path from 'node:path';
import { GLB } from './js/glb.mjs';
import { Game } from './js/game.mjs';
function loadGlb(n){const g=new GLB(n);g.raw=new Uint8Array(readFileSync(path.resolve('data',n)));return g.parse();}
const glb1=loadGlb('FILE0001.GLB'), glb0=loadGlb('FILE0000.GLB');
function die(seed, fire){
  const game=new Game(glb1,glb0,{play(){},sfxCount:0,state:'running'});
  const r=s=>{let x=s>>>0;return()=>(x=(x*1664525+1013904223)>>>0)/4294967296;};
  const rnd=r(seed);
  let f=0;
  while(game.state==='playing' && f<50*60*5){
    game.input.fire=fire;
    game.input.up=true;
    game.input.left=game.input.right=false;
    const c=rnd();
    if (c<0.35) game.input.left=true; else if (c<0.7) game.input.right=true;
    if (game.playerx<40) { game.input.left=false; game.input.right=true; }
    if (game.playerx>260) { game.input.right=false; game.input.left=true; }
    game.frame(); f++;
  }
  const dead=game.state==='dead';
  console.log('DEATH fire='+fire,'seed',seed,'->',dead?('died at '+(f/50).toFixed(0)+'s sim, wave '+(game.wave+1)):'STILL ALIVE at 5min cap');
}
function bot(seed, mode, startShield){
  const game=new Game(glb1,glb0,{play(){},sfxCount:0,state:'running'});
  if (startShield) game.energy.num=startShield;
  const r=s=>{let x=s>>>0;return()=>(x=(x*1664525+1013904223)>>>0)/4294967296;};
  const rnd=r(seed);
  let f=0, maxwave=1;
  while(game.state==='playing' && f<50*60*25){
    game.input.fire=true;
    game.input.left=game.input.right=game.input.up=game.input.down=false;
    const c=rnd();
    if (mode==='walk'){
      if (c<0.25) game.input.left=true; else if (c<0.5) game.input.right=true; else if (c<0.8) game.input.up=true; else game.input.down=true;
      if (game.player_cy<30) { game.input.up=false; game.input.down=true; }
    } else {
      if (c<0.4) game.input.left=true; else if (c<0.8) game.input.right=true; else game.input.down=true;
    }
    if (game.playerx<40) { game.input.left=false; game.input.right=true; }
    if (game.playerx>260) { game.input.right=false; game.input.left=true; }
    game.frame(); f++;
    if (game.wave+1>maxwave) maxwave=game.wave+1;
    if (game.state==='dead') break;
  }
  console.log('M5',mode,'seed',seed,(startShield?('shield'+startShield):'fresh'),'->',game.state,'maxwave',maxwave,'( '+(f/50).toFixed(0)+'s )');
}
die(1,false); die(2,false); die(3,false);
for (const s of [21,22,42,99]) bot(s,'bottom');
bot(0x2f6e2b1,'bottom',86); bot(0x2f6e2b1,'bottom',70);
for (const s of [1,3]) bot(s,'walk');
